main {
  width: 100%;
}

.container {
  max-width: 500px;
  width: 100%;
  margin: 0 auto;
  background-color: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 32px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 28px;
  font-weight: 600;
  margin-bottom: 28px;
  text-align: center;
  color: var(--text-primary);
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Checkbox styling */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid var(--border);
  border-radius: 4px;
  background-color: var(--bg-primary);
  cursor: pointer;
  flex-shrink: 0;
  display: inline-block;
  vertical-align: middle;
  transition: all 0.2s ease;
  margin-right: 12px;
  margin-top: 2px;
}

input[type="checkbox"]:hover {
  border-color: var(--accent);
  background-color: var(--bg-secondary);
}

input[type="checkbox"]:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1), inset 0 0 0 2px var(--accent);
}

input[type="checkbox"]:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1), inset 0 0 0 2px var(--accent);
}

input[type="checkbox"]:checked {
  background-color: var(--accent);
  border-color: var(--accent);
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="white"><path d="M13.78 4.22a.75.75 0 010 1.06l-7.25 7.25a.75.75 0 11-1.06-1.06l7.25-7.25a.75.75 0 011.06 0Z"/></svg>');
  background-repeat: no-repeat;
  background-position: center;
  background-size: 14px;
}

input[type="checkbox"]:checked:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2), inset 0 0 0 2px var(--accent);
}

input[type="checkbox"]:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Checkbox with label wrapper */
input[type="checkbox"] + label {
  display: inline-flex;
  align-items: baseline;
  cursor: pointer;
  user-select: none;
  color: var(--text-primary);
}

input[type="checkbox"] + label a {
  color: var(--accent);
  text-decoration: none;
  border-bottom: 1px solid var(--accent);
  transition: color 0.2s ease;
}

input[type="checkbox"] + label a:hover {
  color: var(--accent-hover);
}

input[type="checkbox"] + label a:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Helper text */
.helper-text {
  font-size: 14px;
  color: var(--text-secondary);
  margin-left: 32px;
}

/* Error message */
.error-message {
  font-size: 14px;
  color: var(--error);
  margin-left: 32px;
}

input[type="checkbox"]:invalid:not(:checked) {
  border-color: var(--error);
}

input[type="checkbox"]:invalid:not(:checked):focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.1), inset 0 0 0 2px var(--error);
  border-color: var(--error);
}

/* Submit button */
.submit-button {
  background-color: var(--accent);
  color: white;
  border: none;
  border-radius: 6px;
  padding: 12px 24px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  margin-top: 8px;
}

.submit-button:hover {
  background-color: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.3);
}

.submit-button:active {
  transform: translateY(0);
  box-shadow: 0 2px 6px rgba(99, 102, 241, 0.2);
}

.submit-button:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.submit-button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Responsive */
@media (max-width: 480px) {
  .container {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
    margin-bottom: 20px;
  }
}

/* Forced Colors mode (high contrast) */
@media (forced-colors: active) {
  input[type="checkbox"] {
    border: 2px solid CanvasText;
    background-color: Canvas;
  }

  input[type="checkbox"]:checked {
    background-color: CanvasText;
    background-image: none;
    content: "✓";
  }

  input[type="checkbox"]:focus {
    outline: 2px solid Highlight;
  }

  .submit-button {
    background-color: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }

  .submit-button:hover {
    background-color: Highlight;
    color: HighlightText;
  }
}
