  border-color: var(--accent);
  background-color: var(--bg-secondary);
}

input[type="checkbox"]:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.15), inset 0 0 0 2px var(--accent);
}

input[type="checkbox"]:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.15), inset 0 0 0 2px var(--accent);
}

input[type="checkbox"]:checked {
  background-color: var(--accent);
  border-color: var(--accent);
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="white"><path d="M13.78 4.22a.75.75 0 010 1.06l-7.25 7.25a.75.75 0 11-1.06-1.06l7.25-7.25a.75.75 0 011.06 0Z"/></svg>');
  background-repeat: no-repeat;
  background-position: center;
  background-size: 14px;
}

input[type="checkbox"]:checked:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.2), inset 0 0 0 2px var(--accent);
}

input[type="checkbox"]:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Checkbox with label wrapper */
input[type="checkbox"] + label {
  display: inline-flex;
  align-items: baseline;
  cursor: pointer;
  user-select: none;
  color: var(--text-primary);
}

input[type="checkbox"] + label a {
  color: var(--accent);
  text-decoration: none;
  border-bottom: 1px solid var(--accent);
  transition: color 0.2s ease;
}

input[type="checkbox"] + label a:hover {
  color: var(--accent-hover);
}

input[type="checkbox"] + label a:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

